function kfProofState(e){if(!e)return {text:'Noch nicht angefragt',kind:'grey'};const expired=(e.warnings||[]).some(w=>w.expires<today());if(expired)return {text:'Abgelaufen · Erneuerung offen',kind:'red'};if((e.warnings||[]).length)return {text:'Ablauf innerhalb von 6 Monaten',kind:'amber'};if(e.status==='submitted')return {text:e.valid?'Bestätigt · Erneuerung eingereicht':'Dokument wird geprüft',kind:'amber'};if(e.status==='rejected')return {text:'Bitte ergänzen',kind:'red'};if(e.status==='not_present')return {text:'Nicht vorhanden',kind:'grey'};if(e.valid)return {text:'Bestätigt & hinterlegt ✓',kind:''};return {text:e.status==='awaiting_upload'?'Dokument fehlt':'Angaben angefragt',kind:'amber'};}
function kfProofCards(m){return kfProofTypes.map(t=>{const e=(state.evidence||[]).find(e=>e.memberId===m.id&&e.kind===t.id),s=kfProofState(e),approved=e?.approved,canEdit=user.role==='participant'||kfCan('manageEvidence');return `<article class="kf-proof-card"><div class="panel-head"><h3>${esc(t.name)}</h3>${tag(s.text,s.kind)}</div><p class="small muted">${approved?`Gültigkeit: ${approved.expiryMode==='unlimited'?'Unbefristet':date(approved.expires)} · bestätigt am ${date(approved.at)}`:e?.available===false?'Du hast angegeben, dass dieser Schein nicht vorhanden ist.':'Vorhandene Scheine benötigen immer ein Dokument und Gültigkeitsangaben.'}</p>${(e?.warnings||[]).map(w=>`<p class="kf-expiry ${w.expires<today()?'overdue':''}">${esc(w.label)}: ${date(w.expires)} · ${w.expires<today()?'abgelaufen':'Erneuerung vorbereiten'}</p>`).join('')}${e?.status==='rejected'?`<div class="notice amber">${esc(e.reviewNote)}</div>`:''}<div class="inline-actions">${canEdit?kfButton(e?'Angaben / Erneuerung':'Angaben machen','proofForm',m.id+':'+t.id,'secondary small'):''}${e?.fileId?kfButton('Eingereichtes Dokument','downloadProof',e.fileId,'secondary small'):''}${approved?.fileId&&approved.fileId!==e.fileId?kfButton('Bestätigtes Dokument','downloadProof',approved.fileId,'secondary small'):''}${e?.status==='submitted'&&['admin','chief'].includes(user.role)&&kfCan('manageEvidence')?kfButton('Dokument prüfen','reviewProof',e.id,'teal small'):''}</div></article>`;}).join('');}
