async function kfExitPreview(){const owner=await kfApiOriginal('state');kfPreviewUserId='';kfOwnerState=null;selectedId='';reportDraft=null;route='dashboard';state=owner;user=state.user;render();}
const kfBookingOriginal=bookingForm;
bookingForm=function(id){const e=byId('Enrollments',id);if(!kfNewReady()){kfBookingOriginal(id);return;}const allowed=state.trainers.filter(t=>(t.examVehicleIds||[]).includes(e.vehicleId));if(!allowed.length){openModal('Noch kein Prüfer freigegeben',empty('Für dieses Fahrzeug ist noch kein Prüfer eingetragen.','Bitte einen Ausbildungschef um die Fahrzeugfreigabe für einen Prüfer bitten.'));return;}openModal('Praktischen Prüfungstermin vereinbaren',`<form id="bookingForm" data-id="${id}"><p class="small muted">${esc(byId('Vehicles',e.vehicleId)?.name)} · ${esc(fmtName(byId('Members',e.memberId)))}</p><div class="form-grid">${select('Freigegebener Prüfer *','trainerId',allowed.map(t=>[t.id,t.name]),'','required')}${field('Terminvorschlag *','begins','','datetime-local','required')}<div class="full">${area('Ort / Nachricht','note','')}</div></div><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button type="submit" class="button teal">${staff()?'Termin festlegen':'Terminvorschlag senden'}</button></div></form>`);};
expiryItems=function(){return (state.evidence||[]).flatMap(e=>(e.warnings||[]).map(w=>({member:byId('Members',e.memberId),label:w.label,expires:w.expires})));};
expirySummary=function(){const list=expiryItems();return list.length?`<div class="notice amber">${list.length} bestätigte Nachweisfrist${list.length===1?'':'en'} ${list.length===1?'liegt':'liegen'} innerhalb von sechs Monaten oder ${list.length===1?'ist':'sind'} bereits abgelaufen. Die Warnung bleibt bis zur bestätigten Erneuerung bestehen.</div>`:`<p class="small muted">Keine bestätigten Nachweise innerhalb der nächsten sechs Monate fällig. Offene Dokumente findest du in der Checkliste.</p>`;};
settingsPage=function(){if(user?.role!=='admin'){$('#content').innerHTML=empty('Nur für den Oberadmin.','Einstellungen sind für dein Konto nicht freigegeben.');return;}const mails=state.mailQueue||[];$('#content').innerHTML=heading('SYSTEMVERWALTUNG','Einstellungen','Mail-Empfänger und Systeminformationen verwaltet ausschließlich der Oberadmin.')+`<div class="two-cols"><div><section class="panel"><h2>Tätigkeitsberichte per E-Mail</h2><form id="reportSettingsForm">${area('Empfänger für fertige Tätigkeitsberichte (durch Komma getrennt)','recipients',state.reportRecipients||'')}<p class="help">Nach Abschluss einer Übung wird der PDF-Bericht an diese Empfänger versendet. Ausbilder und Ausbildungschefs können diese Adressen nicht einsehen oder ändern.</p><button class="button teal" type="submit">Empfänger speichern</button></form></section><section class="panel spacer"><h2>Nachweis-Erinnerungen</h2><p class="small muted">Ab sechs Kalendermonaten vor Ablauf: In-App-Meldung und E-Mail an Teilnehmer und zuständige berechtigte Ausbildungschefs sowie den Oberadmin. Danach monatlich und zusätzlich 30 / 7 Tage vor Ablauf sowie bei Ablauf. Die Warnung bleibt bis zur geprüften Erneuerung sichtbar.</p><p class="help">Mails werden vom Mail-Trigger alle fünf Minuten abgearbeitet. Nachweisprüfung täglich ungefähr 08:00 Uhr Europe/Vienna. Aktivieren: kfErweiterungenEinrichten im aktualisierten Apps Script ausführen.</p></section><section class="panel spacer"><h2>Mail-Versandstatus</h2><div class="table-wrap"><table><thead><tr><th>Ereignis</th><th>Empfänger</th><th>Status</th><th></th></tr></thead><tbody>${mails.slice().reverse().slice(0,30).map(q=>`<tr><td>${esc(q.title)}<small>${date(q.createdAt)}</small></td><td>${esc(state.users.find(u=>u.id===q.userId)?.email||'Konto')}</td><td>${tag({pending:'Vorgemerkt',sent:'Versendet',cancelled:'Nicht mehr aktuell',sending:'Im Versand',failed:'Fehler',unknown:'Zustellung prüfen'}[q.status]||q.status,['failed','unknown'].includes(q.status)?'amber':'grey')}</td><td>${['failed','unknown'].includes(q.status)?kfButton('Versand prüfen','retryMail',q.id,'secondary small'):''}</td></tr>`).join('')||'<tr><td colspan="4">Noch keine Nachweis-Mails vorgemerkt.</td></tr>'}</tbody></table></div></section></div><aside><section class="panel"><h2>Zugänge & Ansichten</h2><div class="inline-actions">${navBtn('Team und Rechte','team','secondary')}${kfButton('Teilnehmeransicht öffnen','previewChooser','','teal')}</div></section><section class="panel spacer"><h2>Systemstand</h2><p class="small muted">Backend ${esc(state.version||'unbekannt')} · ${state.featuresReady?'Zusatz-Tabellen eingerichtet':'Zusatz-Einrichtung noch offen'}</p><p class="help">API: ${esc(window.KF_API_URL)}</p><a class="button secondary small" href="https://github.com/michaelmejtsky/kraftfahrerausbildung" target="_blank" rel="noopener noreferrer">Projektdateien auf GitHub ↗</a><p class="help">Installationspakete und GS-Dateien werden nicht mehr mit der öffentlich erreichbaren App ausgeliefert.</p></section></aside></div>`;};
const kfCourseFormOriginal=renderCourseForm;
renderCourseForm=function(){kfCourseFormOriginal();if(!user)return;const box=$('#questionEditors'),section=box?.closest('.form-section');if(!kfCan('manageQuiz')){if(section)section.innerHTML='<h3>Theoriequiz</h3><p class="help">Du darfst die Kursinhalte bearbeiten. Quizfragen und Lösungen verwaltet ein dafür berechtigtes Konto; sie bleiben beim Speichern unverändert.</p>';}else if(!kfCan('manageCourses')&&section){$$('#courseForm input, #courseForm textarea, #courseForm select, #courseForm [data-action]').forEach(el=>{if(!section.contains(el)&&el.dataset.action!=='close')el.disabled=true;});$('#courseForm').insertAdjacentHTML('afterbegin','<div class="notice">Dein Recht gilt für das Theoriequiz. Die übrigen Kursdaten bleiben unverändert.</div>');}};
const kfCollectCourseOriginal=collectCourse;
collectCourse=function(){const before=structuredClone(courseDraft);kfCollectCourseOriginal();if(!kfCan('manageCourses'))courseDraft={...before,quiz:courseDraft.quiz};if(!kfCan('manageQuiz'))courseDraft.quiz=before.quiz;};
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-kf]');if(!b||b.disabled||busy)return;const a=b.dataset.kf,id=b.dataset.id||'';if(kfPreviewUserId&&!['exitPreview','downloadProof'].includes(a)){toast('Die Vorschau ist schreibgeschützt.',true);return;}try{switch(a){case 'previewChooser':kfPreviewChooser();break;case 'preview':operation(()=>kfEnterPreview(id));break;case 'exitPreview':operation(kfExitPreview);break;case 'newStaff':kfStaffEditor();break;case 'editStaff':kfStaffEditor(id);break;case 'sendStaffInvite':{const target=state.users.find(x=>x.id===id);if(!target||!target.active)throw Error('Aktives Konto nicht gefunden.');if(kfStaffEditorDirty)throw Error('Bitte Änderungen am Zugang zuerst speichern und anschließend die Einladung senden.');operation(async()=>{const r=await api('invite',{userId:id,sendEmail:true});if(!r.emailSent)throw Error('Die E-Mail konnte nicht als versendet bestätigt werden.');openModal('Einladung versendet',`<p>Die Einladung wurde an die im Konto gespeicherte E-Mail-Adresse gesendet.</p><p class="small muted">Der Link ist 7 Tage gültig und ersetzt frühere offene Links. Ausbildungsnachweise bleiben bestehen.</p><label>Persönlicher Einladungslink<input id="inviteUrl" readonly value="${esc(r.url)}"></label><div class="form-actions">${btn('Link kopieren','copyInvite','','teal')}${btn('Schließen','close','','secondary')}</div>`);});break;}case 'proofForm':{const [mid,kind]=id.split(':');kfProofForm(mid,kind);break;}case 'reviewProof':kfReviewForm(id);break;case 'downloadProof':operation(async()=>downloadData(await api('download',{fileId:id})));break;case 'requestProofs':kfFeatureRequired();operation(async()=>{const r=await api('requestEvidence',{memberId:id});await load();toast(r.count?'Nachweise angefragt. E-Mail ist vorgemerkt.':'Die offenen Nachweise wurden bereits angefragt.');});break;case 'requestAllProofs':kfFeatureRequired();openModal('Nachweise für alle aktiven Teilnehmer anfragen?',`<p>Bereits bestätigte Nachweise bleiben erhalten. Für noch nicht angefragte Punkte werden In-App-Anfragen und E-Mails vorgemerkt.</p><div class="form-actions">${btn('Abbrechen','close','','secondary')}${kfButton('Anfragen vormerken','confirmAllProofs','','teal')}</div>`);break;case 'confirmAllProofs':operation(async()=>{await api('requestAllEvidence');closeModal();await load();toast('Offene Nachweise angefragt; Mails sind vorgemerkt.');});break;case 'retryMail':openModal('Zustellung vor erneutem Versand prüfen',`<form id="kfRetryMailForm" data-id="${id}"><div class="notice amber">Bei unterbrochenem Versand ist unklar, ob die Mail bereits zugestellt wurde. Prüfe zuerst den gesendeten Postausgang, damit keine doppelte Mail entsteht.</div>${check('Ich habe geprüft: Diese Mail wurde nicht zugestellt.','confirm',false,'required')}<div class="form-actions"><button type="submit" class="button teal">Erneuten Versand vormerken</button></div></form>`);break;}}catch(e){toast(e.message,true);}});
document.addEventListener('submit',ev=>{const form=ev.target;if(!['kfStaffForm','kfPreviewForm','kfProofForm','kfReviewForm','kfRetryMailForm'].includes(form.id))return;ev.preventDefault();if(busy)return;operation(async()=>{const d=new FormData(form);if(form.id==='kfPreviewForm'){await kfEnterPreview(d.get('userId'));return;}kfFeatureRequired();if(form.id==='kfStaffForm'){const permissions=Object.fromEntries(Object.keys(kfRightLabels).map(k=>[k,d.has('right_'+k)])),record={id:form.dataset.id,name:d.get('name'),email:d.get('email'),number:d.get('number'),role:d.get('role'),managerId:d.get('managerId')||'',active:d.has('active'),permissions,examVehicleIds:state.vehicles.filter(v=>d.has('exam_'+v.id)).map(v=>v.id)};await api('saveUser',record);closeModal();await load();toast('Zugang und Berechtigungen gespeichert.');}else if(form.id==='kfProofForm'){const available=d.get('available')==='yes',kind=form.dataset.kind,meta={memberId:form.dataset.member,kind,available,expiryMode:d.get('expiryMode'),expires:d.get('expires'),issueDate:d.get('issueDate'),note:d.get('note'),classes:kind==='licence'?CLASSES.filter(c=>d.has('proofClass_'+c)).map(c=>({class:c,expires:d.get('proofExpiry_'+c)})):[]},file=d.get('file'),approve=d.has('approve')&&['admin','chief'].includes(user.role);let result;if(available&&file?.size){if(file.size>2*1024*1024)throw Error('Maximal 2 MB pro Nachweis.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Datei konnte nicht gelesen werden.'));reader.readAsDataURL(file);});result=await api('uploadEvidence',{...meta,approve,name:file.name,mime:file.type,base64});}else{result=await api('declareEvidence',meta);if(approve&&available&&result.fileId)result=await api('reviewEvidence',{id:result.id,approved:true,note:meta.note||'Vorhandenes Dokument und Angaben geprüft.'});}closeModal();await load();toast(available?(result.status==='approved'?'Nachweis mit Dokument bestätigt.':file?.size?'Dokument an Ausbildungschef zur Prüfung übermittelt.':'Angaben gespeichert. Das Dokument fehlt noch.'):'Als nicht vorhanden erfasst.');}else if(form.id==='kfReviewForm'){await api('reviewEvidence',{id:form.dataset.id,approved:d.get('approved')==='yes',note:d.get('note')});closeModal();await load();toast('Prüfentscheidung gespeichert.');}else if(form.id==='kfRetryMailForm'){await api('retryMail',{id:form.dataset.id,confirmNotDelivered:d.has('confirm')});closeModal();await load();toast('Erneuter Versand vorgemerkt.');}});});
const kfApiWithPreview=api;
api=async function(action,data={}){try{return await kfApiWithPreview(action,data);}finally{if(action==='logout'){kfOwnerState=null;kfPreviewUserId='';}}};
const kfOperationOriginal=operation;
operation=async function(fn){try{return await kfOperationOriginal(fn);}finally{kfDecorate();}};
const kfLoginPageOriginal=loginPage;
loginPage=function(message=''){kfPreviewUserId='';kfOwnerState=null;kfLoginPageOriginal(message);const bar=$('#kfViewBar');if(bar)bar.hidden=true;};
if(user)render();
